# x_g7: residential and general early-design knowledge (area measurement, DIN 277 areas, setback
# areas and plot ratios, access type per stair, row-house depth, entrance recess, minimum dwelling
# equipment). All items are supplements.

C['g7_flat_area'] = cite('page_0148', 'The area of a house or flat includes the floor area of all rooms which belong exclusively to the house', 'page_0148_intent_001')
C['g7_clear_area'] = cite('page_0148', 'The floor area of a room is determined from the clearance space between building components and starts from the face of the cladding of the building component', 'page_0148_intent_002')
C['g7_gfa'] = cite('page_0075', 'The gross floor area is the sum of the plan area of all levels (without usable roof areas), measured between the external dimensions of the surrounding building elements at floor height.')
C['g7_cfa'] = cite('page_0075', 'The constructional floor area is the sum of the plan area of all surrounding building elements (walls, columns, pillars, chimneys, non-accessible shafts, door openings, niches, apertures) measured between the external dimensions at floor height.')
C['g7_nfa'] = cite('page_0075', 'The net floor area is the usable floor area between the building elements (without door and window openings, cut-outs and niches) measured at floor level.')
C['g7_setback_depth'] = cite('page_0076', 'The depth of setback areas differs in the various state building regulations (LBO)). According to the model building regulations (MBO), it is 0.4 × H, but at least 3 m (0.2 × H, min. 3 m for commercial and industrial areas). In front of the outside walls of building classes 1 and 2 with not more than three overground storeys, 3 m depth is also sufficient.')
C['g7_setback_height'] = cite('page_0076', 'The depth of the setback area is measured according to wall height → ④ – ⑥. This is measured at right angles to the wall. Wall height means the dimension from ground level to upper extent of the wall or to the intersection of the wall with the roof covering → ④. The height of roofs with a pitch of ≤70° is included to one third, ≥70° fully with the wall height → ⑤.')
C['g7_setback_public'] = cite('page_0076', 'They may also lie on public traffic, green and water areas, but only to their centre.')
C['g7_setback_proj'] = cite('page_0076', 'Building elements projecting from the outside wall (cornices, roof overhang) are not considered in the measurement of setback areas → ⑧. Projections remain unconsidered if they:\n– take up altogether less than one third of the width of the outside wall\n– project by a max. 1.50 m in front of the outside wall\n– stay at least 2 m distant from the opposing plot boundary')
C['g7_grz'] = cite('page_0075', 'the plot coverage ratio determines the permissible ratio of built area on the plot (plan area of building including garages, parking places and their access, subsidiary areas... and underground facilities beneath the plot)')
C['g7_gfz'] = cite('page_0075', 'the floor-area ratio (determines the permissible ratio of storey area (external dimensions of all full floors, without subsidiary areas..., balconies, loggias, terraces and structures which are permissible inside setback areas) to the plot area.')
C['g7_one_per_floor'] = cite('page_0154', "There is access to only one flat on each floor. This is relatively uneconomic due to the high proportion of the total floor area taken up for access, but can often give the feeling of living in a 'stacked terrace'. The flats are also marketed as town villas. There is a general limitation to four floors without a lift.", 'page_0154_intent_008')
C['g7_three_per_floor'] = cite('page_0154', 'Three flats per floor offers a favourable combination of residential quality and value for money.', 'page_0154_intent_001')
C['g7_row_depth'] = cite('page_0156', 'Building in a row restricts the possibilities for direct lighting to two façades so that, with economic building depths of up to 12 m and widths between 4 and 8 m, the existence of a badly lit or dark middle zone containing the stairs, subsidiary rooms and often also the dining area becomes unavoidable.', 'page_0156_intent_007')
C['g7_recess'] = cite('page_0158', 'Entrance recesses should be at least 1.25 m (better 1.50 m) wide and approx. 1.00 m deep, so that two people can wait comfortably and protected in front of the door', 'page_0158_intent_009')
C['g7_kitchen_req'] = cite('page_0161', 'According to the building regulations, every house or flat must have at least one kitchen or kitchenette for cooking.', 'page_0161_intent_028')
C['g7_store_req'] = cite('page_0174', 'The building regulations require that every flat or house be provided with a sufficiently large storeroom.', 'page_0174_intent_012')
# existing knowledge point used as secondary basis
C['g7_height_full'] = cite('page_0075', 'Floor areas are included in the calculation either completely (for rooms and parts of rooms with a clear ceiling height of at least 2 m)')

ITEMS += [
    # ------------------------------------------------------------------ area measurement
    dict(project='fzk_house', derived_from=[], pairing='supplement', question_type='diagnosis',
         question='For the six ground-floor rooms, the model gives both a GrossFloorArea and a NetFloorArea (e.g. Wohnen 25.99 / 25.21 m², Küche 16.31 / 16.31 m²). The walls are modelled as bare "Leichtbeton" with no plaster layer. Which of the two values matches how room areas are measured for a dwelling\'s housing area, and is the model consistent about it?',
         answer='NetFloorArea is the right value, but the kitchen is inconsistent. Under the housing-area regulation Neufert summarises, a room\'s floor area is the clear space between building components, measured from the face of their cladding (plaster, linings), so a figure taken to the raw wall overstates it. Each room\'s GrossFloorArea equals its space solid, which runs between the raw Leichtbeton wall faces (Wohnen 7.01 × 3.71 m ≈ 25.99 m²). For five rooms, NetFloorArea is exactly 97 % of that: Flur 11.53 → 11.19, Buero 12.99 → 12.60, Bad 12.50 → 12.13, Schlafzimmer 22.07 → 21.41, Wohnen 25.99 → 25.21 m². This is a flat 3 % deduction, evidently for the wall finishes the model does not show. The Küche gets no deduction (16.31 m² for both values), so it is measured to the raw walls. With the same 3 % it would be ≈ 15.82 m², and the ground floor would total ≈ 98.34 m² instead of the listed 98.83 m² (101.39 m² raw).',
         evidence=['GrossFloorArea / NetFloorArea (Qto): Flur 11.5314 / 11.1855, Buero 12.985 / 12.5955, Bad 12.5027 / 12.1276, Schlafzimmer 22.0725 / 21.4103, Wohnen 25.9886 / 25.2089, Küche 16.3055 / 16.3055 m².',
                   'Space solids end at the raw faces of the walls, e.g. Wohnen x 4.69…11.70, y 0.30…4.01 m; walls "Leichtbeton 102890359 300/240" are single-layer, with no plaster layer modelled.'],
         hidden_knowledge='Housing-area regulation (2003): room floor area = clear space between building components measured from the face of their cladding (finished surfaces).',
         basis=[C['g7_clear_area'], C['g7_flat_area']],
         rubric=['Chooses NetFloorArea (measured to finished faces) over GrossFloorArea', 'Identifies the uniform 97 % ratio for five rooms', 'Flags the Küche as having no deduction', 'Gives corrected values (≈15.8 m², ≈98.3 m²)']),
    dict(project='fzk_house', derived_from=[], pairing='supplement', question_type='derivation',
         question='Using DIN 277 terms, derive three figures for the FZK house: the gross floor area of the whole house, the constructional floor area of its ground floor, and the net floor area of both levels together.',
         answer='Gross floor area ≈ 240 m², ground-floor constructional area ≈ 18.6 m², net floor area ≈ 192.7 m². Gross floor area is measured over the external dimensions of the enclosing elements at floor height. Both the Erdgeschoss and the Dachgeschoss lie within the 12.00 × 10.00 m outer wall faces, so it is 2 × 120.0 = 240.0 m². Net floor area is the area between the building elements. On the ground floor, the six room solids, which run between the raw wall faces, add up to 101.4 m². In the attic, the Galerie\'s 11.40 × 9.40 = 107.16 m² minus the 15.80 m² stair void (a cut-out, not floor) gives ≈ 91.4 m². Together that is ≈ 192.7 m², about 80 % of the gross floor area. Constructional floor area is the plan area of the walls themselves. On the ground floor it is 120.0 − 101.4 ≈ 18.6 m², which matches the 0.30 m outer ring (120.0 − 107.16 = 12.84 m²) plus ≈ 5.8 m² of 0.24 m inner walls. DIN 277 makes no height reduction, unlike the housing-area calculation, so the Galerie\'s low eaves zones count in full here.',
         evidence=['External walls Wand-Ext-ERDG-1…4 and Wand-Ext-OG-1…4: outer faces at x 0.00/12.00 and y 0.00/10.00 m, 0.30 m thick, on both storeys (Erdgeschoss ±0.00, Dachgeschoss +2.70 m).',
                   'Ground-floor space solids (GrossFloorArea): Flur 11.531, Buero 12.985, Bad 12.503, Schlafzimmer 22.073, Wohnen 25.989, Küche 16.305 m² (sum 101.39 m²).',
                   'Internal walls Wand-Int-ERDG-1…5, 0.24 m thick, lengths ≈ 3.71, 5.69, 7.11, 4.29, 3.50 m.',
                   'Galerie space 0.30…11.70 × 0.30…9.70 m (GrossFloorArea 107.16 m²); Slab-033 opening x 7.44–11.70, y 0.30–4.01 m (15.80 m²).'],
         hidden_knowledge='DIN 277: gross floor area over external dimensions of all levels; constructional floor area = plan area of the enclosing elements; net floor area = usable area between the elements, without openings and cut-outs.',
         basis=[C['g7_gfa'], C['g7_cfa'], C['g7_nfa']],
         rubric=['Gross floor area 240 m² from external dimensions of both levels', 'Ground-floor net ≈101.4 m² and constructional ≈18.6 m² (walls)', 'Deducts the stair void from the attic net area', 'Total net ≈192–193 m²']),
    # ------------------------------------------------------------------ setback areas and plot ratios
    dict(project='fzk_house', derived_from=[], pairing='supplement', question_type='compliance',
         question='Treat the modelled terrain "Gelaende" (≈18 × 16 m, extending 3.0 m beyond the house on every side) as the plot. How deep a setback area must the house keep free in front of its walls, does the plot provide it, and what plot coverage ratio does the house produce?',
         answer='3 m on every side. The terrain gives exactly 3.0 m from the walls, but whether that suffices depends on the 0.5 m roof overhang (see below); the plot coverage ratio is ≈ 0.42. Under the model building regulations (MBO; state LBOs differ) the setback depth is 0.4 × H, but at least 3 m. H is the wall height from ground level to the intersection with the roof covering, plus one third of the height of a roof pitched ≤ 70°. Eaves walls: H ≈ 3.4 m + ⅓ × ≈ 2.9 m of roof ≈ 4.4 m, so 0.4 H ≈ 1.8 m. Even the gable walls taken at their full height to the ridge covering (+6.32 m) only need 0.4 × 6.32 ≈ 2.5 m. Both are below the 3 m minimum. For a detached one-family house with two storeys (building class 1–2, not more than three storeys), 3 m is sufficient in any case. The terrain runs from −3.0 to 15.0 m in x and from −3.0 to 13.0 m in y around the 0–12 × 0–10 m house, exactly 3.0 m on each side of the walls. Projecting elements such as cornices and roof overhangs are disregarded only if they take up altogether less than one third of the wall width, project at most 1.50 m and stay at least 2 m from the opposing boundary. The 0.5 m overhang meets the last two conditions (2.5 m from the terrain edge) but runs along the whole length of every wall, so it fails the one-third condition; measured from its edge, only 2.5 m of the required 3 m remain, 0.5 m short. Only if roof overhangs were taken as exempt regardless of these conditions would the house just comply. (This assumes the terrain edge is a boundary with private land: if it bordered a public road, green or water area, the setback area could extend onto it up to its centre, and the shortfall would disappear; the model shows no such neighbour.) Plot coverage = built area / plot area; the model has no garage, parking or underground facility to add, so built area = 120 m² and the ratio is 120 / 288 ≈ 0.42. The floor-area ratio is also ≈ 0.42 if only the ground floor counts as a full storey, or ≈ 0.83 if the attic did.',
         evidence=['IfcSite "Gelaende" 0KMpiAlnb52RgQuM1CwVfd: x −3.0…15.0, y −3.0…13.0 m, top at ±0.00.',
                   'House outline 12.00 × 10.00 m (x 0…12, y 0…10); eaves walls Wand-Ext-OG-2/-4 top +3.37 m; gable walls Wand-Ext-OG-1/-3 top +6.09 m.',
                   'Roof slabs Dach-1/Dach-2: x −0.5…12.5, y −0.5…10.5 (0.5 m overhang), 2.91 to 6.32 m, 30° pitch, ridge along y = 5.0.',
                   'Storeys: Erdgeschoss ±0.00, Dachgeschoss +2.70 (attic under the roof).'],
         hidden_knowledge='MBO setback depth 0.4 H, min. 3 m (3 m suffices for classes 1–2 with ≤ 3 overground storeys; LBOs differ); H to the roof-covering intersection plus ⅓ of a roof ≤ 70°; projections (cornices, roof overhangs) disregarded only if < ⅓ of the wall width, ≤ 1.50 m and ≥ 2 m from the boundary. setback areas lie on the plot but may extend onto adjoining public traffic, green and water areas up to their centre. Plot coverage ratio = built area (building plus garages, parking, subsidiary and underground facilities) / plot area.',
         basis=[C['g7_setback_depth'], C['g7_setback_height'], C['g7_setback_proj'], C['g7_setback_public'], C['g7_grz'], C['g7_gfz']],
         rubric=['Computes 0.4 H < 3 m, so 3 m governs', 'Applies the ⅓ roof addition', 'Finds the terrain gives exactly 3.0 m from the walls and checks the 0.5 m overhang against the projection conditions (full-length overhang fails the < ⅓ width test → 2.5 m, 0.5 m short; complies only if overhangs are exempt)', 'Plot coverage ≈ 0.42']),
    dict(project='fantasy_residential_building_1', derived_from=[], pairing='supplement', question_type='derivation',
         question='The two wings of the apartment building have hipped roofs. Their outer walls rise to +10.72 m and the roof covering reaches its ridge at +12.37 m. On the first and second floors, 3.0 m deep balconies (Balcony 1/3 and 2/6) run along about 29.7 m of the 32.85 m long west and east façades. How deep a setback area must be kept free in front of these long façades, and from where is it measured?',
         answer='About 4.5 m, measured from the outer edge of the balconies, so the clear strip reaches about 7.5 m from the façade walls. H is the wall height to the roof covering plus one third of the roof height, because the pitch is ≈ 31° (≤ 70°): 10.72 + (12.37 − 10.72) / 3 ≈ 11.27 m. 0.4 × 11.27 ≈ 4.5 m, which is above the 3 m minimum. This is the MBO rule; state LBOs differ. The 3 m concession for small buildings does not apply: it is limited to building classes 1–2, and a building with six flats is in classes 3–5 by the book\'s gloss (more than two flats). Projecting elements (cornices, roof overhangs and the like) are disregarded only if they take up altogether less than one third of the wall width, project no more than 1.50 m and stay at least 2 m from the opposing boundary. The balconies fail the first two tests: they run along ≈ 90 % of the façade length and are 3.0 m deep. So they count as part of the building (the 0.6 m eaves overhang lies within their depth and does not matter), and the 4.5 m strip starts at their outer edge (x −16.01 on the west, ≈ +10.0 on the east), about 7.5 m from the walls at x −13.01 and +6.99.',
         evidence=['Outer walls "STB 30.0 - Sichtbeton 1" 1zd7CBFUPAlvZ18vcQYkzn (x −13.01…−12.71) and 2odsreyuHD88JhNDddqWzy (x 6.69…6.99): y −22.10…10.75 m, top +10.72 m.',
                   'Roof covering "Basisdach:Titanzink - Eindeckung" slabs, e.g. west wing x −13.61…−6.41: z +10.20 at the eaves to +12.37 m at the ridge (rise ≈ 2.17 m over ≈ 3.6 m, ≈ 31°).',
                   'Balcony 1 / Balcony 3: x −16.01…−13.01, y −18.9…10.75 m (3.0 × 29.65 m); Balcony 2 / Balcony 6: x 6.99…9.99/10.01; balcony columns at x −16.01 and +9.7…9.96.',
                   'Six flats (two per storey on Ground, First, Second Floor); ground level ±0.00.'],
         hidden_knowledge='MBO setback depth 0.4 H (min. 3 m; 3 m concession only for classes 1–2 with ≤ 3 overground storeys; LBOs differ); H = wall height to roof-covering intersection + ⅓ of a roof ≤ 70°; projections are disregarded only if < ⅓ of wall width, ≤ 1.50 m deep and ≥ 2 m from the boundary.',
         basis=[C['g7_setback_depth'], C['g7_setback_height'], C['g7_setback_proj']],
         rubric=['H ≈ 11.3 m with the ⅓ roof addition', '0.4 H ≈ 4.5 m (> 3 m; no class 1–2 concession)', 'Balconies are too long and too deep to be ignored', 'Measures from the balcony edge (≈ 7.5 m from the wall)']),
    dict(project='fantasy_office_building_1', derived_from=[], pairing='supplement', question_type='derivation',
         question='The office building has flat roofs. Its long west and east façades (x = −12.01 and +9.99 m) end in a parapet at +19.80 m. On the two 22 m wide end façades, the central 14 m (the two core blocks, x −8.01 to +5.99) rises flush with the façade to +24.30 m. If the plot lies in a commercial area, how deep must the setback areas in front of the long façades and the end façades be? How would they change in a residential or mixed area?',
         answer='In a commercial area: ≈ 4.0 m in front of the long façades and ≈ 4.9 m in front of the core part of the end façades (≈ 4.0 m for their outer 4 m parts). Elsewhere the depths double, to ≈ 7.9 m and ≈ 9.7 m. Under the model building regulations (MBO; the state LBOs differ) the setback depth is a factor × H, but at least 3 m. H is the wall height from ground level to the top of the wall, with no roof addition because the roofs are flat. Long façades: H = 19.80 m, so 0.2 H = 3.96 m in commercial and industrial areas and 0.4 H = 7.92 m elsewhere. Core sections: H = 24.30 m, so 0.2 H = 4.86 m and 0.4 H = 9.72 m. All of these exceed the 3 m minimum. The MBO concession that 3 m suffices for building classes 1–2 with not more than three overground storeys does not apply: the building has five storeys (EG–OG4). Because the cores run up flush with the end façades, they set the deepest strip at both ends. Setting the core tops back from the façade would let the end walls be judged at 19.80 m.',
         evidence=['Walls "STB 25.0 WD 12.0" on the outer lines, e.g. 0N9CSx_ib7HQ7izEW$Ow$w (x −12.01…−8.13, y −21.25…−20.88) top +19.80 m; parapets 2TThLe7Hj4EeSrbZELDLHk / 2TThLe7Hj4EeSrbZELDLJL at x −12.01 and +9.99, +19.20…19.80 m.',
                   'Core walls "STB 20.0 WD 12.0" 1BjNOqpyX8MBF4NmZ4FziL (x −7.89…5.99, y −21.25…−20.88) and 0N9CSx_ib7HQ7izEW$OwkJ (y 10.38…10.75): 0.00 to +24.30 m, flush with the end façades.',
                   'Roofs "Basisdach:Stb 20, insulated": wings at +18.79…19.27 m, cores at +23.68…24.16 m (flat).',
                   'Overall plan x −12.01…9.99 (22.0 m), y −21.25…10.75 (32.0 m); EG at ±0.00.',
                   'Storeys EG 0.00, OG1 4.80, OG2 9.60, OG3 14.40, OG4 19.20 m.'],
         hidden_knowledge='MBO setback depth 0.4 H, or 0.2 H in commercial and industrial areas, min. 3 m (3 m suffices only for classes 1–2 with ≤ 3 overground storeys; state LBOs differ); H = wall height from ground to top of wall (roof addition only for pitched roofs).',
         basis=[C['g7_setback_depth'], C['g7_setback_height']],
         rubric=['Uses 0.2 H for commercial and 0.4 H otherwise, min 3 m', 'Long façades: ≈3.96 / 7.92 m from H = 19.80 m', 'End façades governed by the 24.30 m cores: ≈4.86 / 9.72 m', 'No roof addition for flat roofs']),
    # ------------------------------------------------------------------ access type and building depth
    dict(project='fantasy_residential_building_1', derived_from=[], pairing='supplement', question_type='intent',
         question='Count how many flats each of the two stairwells serves per floor and name the resulting access type. Judge it: what share of each floor does the stairwell take, and how many storeys could this type have if the lifts were left out?',
         answer='Each stairwell serves one flat per floor. Stairwell 1 serves only the west flats and Stairwell 2 only the east flats, with one front door per floor in each. The building is therefore two one-flat-per-floor stacks side by side, the "stacked terrace" or town-villa type. Neufert calls this type relatively uneconomic because access takes a high share of the floor area. Here the 20.81 m² stairwell serves one ≈ 154.8 m² flat (west ground floor: 18.07 + 4.33 + 38.45 + 36.53 + 26.42 + 8.18 + 13.37 + 9.42), i.e. ≈ 11.9 % of each floor (20.81 / 175.6). If one core served both flats of a floor (two flats per floor, the most common type), the share would fall to ≈ 6.3 % (20.81 / 330.4). Three flats per floor would give an even better balance of quality and cost. Without lifts, this type is generally limited to four floors, so the three storeys here do not need the lifts; lifts are only required above five full floors anyway. The lifts are a choice for comfort and accessibility, not a requirement.',
         evidence=['Stairwell 1 (x −12.71…−7.31, y −22.10…−17.50) and Stairwell 2 (x 1.29…6.69), 20.81 / 20.48 m², each one space through all floors (to +9.55 m), with lift doors "TU SF 2 - Lift Zentral".',
                   'Front doors "TU DF 1 - Haustüre:Front Door" at y −17.56…−17.35 on each floor: x −12.41…−11.28 (west, e.g. 0wWzhGA85BmABLFeqDOnTP) and x 5.25…6.39 (east, e.g. 0wWzhGA85BmABLFeqDOnV0), opening into the Wardrobes.',
                   'West ground-floor flat: Wardrobe 18.07, Toilet 4.33, Kitchen and Dining 38.45, Living 36.53, Bedroom 26.42, Office 8.18, Bathroom 13.37, Utility 9.42 m² (154.77 m²).',
                   'Storeys: Ground, First, Second Floor (+ Roof at +10.20 m); ground-floor Lobby (21.27 m²) between the two stairwells.'],
         hidden_knowledge='One flat per floor: uneconomic share of access area, generally max. four floors without a lift; two flats per floor is the most common, three per floor a favourable balance; lifts required above five full floors.',
         basis=[C['g7_one_per_floor'], C['g7_three_per_floor'], C['two_per_floor'], C['lift_req']],
         rubric=['Identifies one flat per floor per stair (not a shared two-flat core)', 'Computes the access share ≈ 12 % and compares with a shared core (≈ 6 %)', 'States the four-floor limit without lift, so lifts are not required here']),
    # ------------------------------------------------------------------ entrance and minimum equipment
    dict(project='fzk_house', derived_from=[], pairing='supplement', question_type='compliance',
         question='The FZK house has seven spaces: Flur, Buero, Bad, Schlafzimmer, Wohnen, Küche and the attic Galerie. Does the dwelling contain the rooms that building regulations require in every house or flat? If one is missing, where could it go?',
         answer='No, the dwelling has no storeroom. Building regulations require every house or flat to have at least one kitchen or kitchenette, a bathroom, and a sufficiently large storeroom. The house has the Küche (16.3 m², open to the hall and the living room, but still a kitchen) and the Bad (12.1 m², the only sanitary room). No space serves as a storeroom: the other rooms are the bedroom, office, living room, hall and Galerie, and the model has no cellar or utility room. The natural place for one is the low eaves zone of the Galerie. Its clear height is only 0.67 m at the eaves walls, so these strips count for only half or nothing of the living area anyway. Alternatively, a walk-in store could be partitioned off the 1.74 m wide Flur at the cost of a narrower hall.',
         evidence=['Spaces: Erdgeschoss Flur 11.19, Buero 12.60, Bad 12.13, Schlafzimmer 21.41, Wohnen 25.21, Küche 16.31 m²; Dachgeschoss Galerie (107.16 m² gross, 74.51 m² height-reduced).',
                   'No IfcSpace for storage, cellar or utility; storeys only Erdgeschoss and Dachgeschoss.',
                   'Galerie clear height ≈ 0.67 m at the eaves walls, rising ≈ 0.577 m per m (30° roof).',
                   'Flur: x 0.30…7.41, y 4.01…5.75 m (≈ 1.74 m wide).'],
         hidden_knowledge='Building regulations require every house or flat to have at least a kitchen/kitchenette, a bathroom and a sufficiently large storeroom.',
         basis=[C['g7_kitchen_req'], C['g7_store_req'], C['bath_min']],
         rubric=['Checks kitchen and bathroom as present', 'Identifies the missing storeroom as a regulatory deficiency', 'Proposes a plausible location (Galerie eaves or hall)']),
]
